module tournament_scheduler(input clk,input rst_n,input start,input [3:0] n_in,input [3:0] m_in,output reg [5:0] round_index,output reg [4:0] game_count,output reg [4:0] player1_idx,output reg [4:0] player2_idx,output reg output_valid,output reg done);reg [2:0] state;reg [3:0] n_val,m_val;reg [7:0] total_players,games_per_round,total_valid_pairs,game_counter,total_games_emitted;reg [3:0] i_reg,j_reg;reg [5:0] round_index_reg;reg [4:0] player1_idx_reg,player2_idx_reg;reg output_valid_reg,done_reg;localparam IDLE=3'd0,SETUP=3'd1,GEN_ROUND=3'd2,DONE_STATE=3'd3;always @(posedge clk)beginif(!rst_n)beginstate<=IDLE;n_val<=4'd0;m_val<=4'd0;total_players<=8'd0;games_per_round<=8'd0;total_valid_pairs<=16'd0;game_counter<=8'd0;total_games_emitted<=16'd0;i_reg<=4'd0;j_reg<=4'd0;round_index_reg<=5'd0;player1_idx_reg<=4'd0;player2_idx_reg<=4'd0;output_valid_reg<=1'b0;done_reg<=1'b0;end else beginif(start==1)beginif(state==IDLE)beginstate<=SETUP;n_val<=n_in;m_val<=m_in;endendcase(state)SETUP:beginif(n_val>4||n_val<1||m_val>4||m_val<2)beginendtotal_players<=n_val*m_val;games_per_round<=total_players>>1;total_valid_pairs<=(total_players*(total_players-1)/2)-(m_val*(n_val*(n_val-1)/2));if(total_valid_pairs==0)beginstate<=DONE_STATE;end else beginstate<=GEN_ROUND;i_reg<=4'd0;j_reg<=4'd1;endendGEN_ROUND:beginif(i_reg<total_players-1)beginif(j_reg<=total_players-1)beginif((i_reg/n_val)!=(j_reg/n_val))beginif(game_counter<games_per_round)beginplayer1_idx_reg<=i_reg;player2_idx_reg<=j_reg;output_valid_reg<=1'b1;game_counter<=game_counter+1;total_games_emitted<=total_games_emitted+1;if(game_counter==games_per_round)beginround_index_reg<=round_index_reg+1;endendendif(j_reg<total_players-1)beginj_reg<=j_reg+1;end else begini_reg<=i_reg+1;j_reg<=i_reg+1;endendendif(total_games_emitted==total_valid_pairs)beginstate<=DONE_STATE;endendDONE_STATE:beginendcaseendendmodule